func TestFounderPlanAcceptsLongerLivedManifestDelegation(t *testing.T) {
	fixture := newFounderPlanFixture(t)
	peerPublicWire, err := trust.EncodeDelegatedPublicKey(fixture.authority.peerPublic)
	if err != nil {
		t.Fatal(err)
	}
