func (fixture founderPlanFixture) launchAuthorization(
	t *testing.T,
	plan VerifiedFounderPlan,
	row FounderPeerRow,
	planDigestPin string,
	rowDigestPin string,
) LaunchAuthorization {
	t.Helper()
	client := newFakeObjectStorageClient()
	client.setNow(fixture.now)
	controllerSlots := slices.Clone(fixture.plan.ControllerSlots)
	capabilities := make([]trust.Capability, 0, 3)
	for _, domain := range []string{domainBootstrapHead, domainBootstrapIntent, domainBootstrapResult,
		domainBootstrapCandidate, domainBootstrapProgress} {
		capabilities = append(capabilities, trust.Capability{
			Domain: domain, DeploymentID: fixture.plan.DeploymentID, Cell: string(fixture.plan.Cell),
			Environment: fixture.plan.Environment, Role: roleController, Slots: slices.Clone(controllerSlots), Actions: []string{"sign"},
		})
	}
	peerPublicWire, err := trust.EncodeDelegatedPublicKey(fixture.authority.peerPublic)
	if err != nil {
		t.Fatal(err)
	}
	ledgerGrant, err := trust.SignDelegation(trust.Delegation{
		SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID(t, fixture.authority.peerPublic),
		SubjectPublicKey: peerPublicWire, Capabilities: capabilities,
	}, fixture.now.Add(-time.Minute), fixture.now.Add(23*time.Hour), fixture.authority.rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	delegation, err := trust.VerifyDelegationCurrent(ledgerGrant, fixture.authority.roots, fixture.now, fixture.policy)
	if err != nil {
		t.Fatal(err)
	}
	anchor := fixture.anchor.Anchor()
	config := LedgerConfig{
		DeploymentID: anchor.DeploymentID, Cell: anchor.Cell, ClusterID: anchor.ClusterID,
		InitialRegionIntentGeneration: anchor.InitialRegionIntentGeneration,
		InitialRegionIntentSHA256:     anchor.InitialRegionIntentSHA256,
		Namespace:                     anchor.StorageDomain.Namespace, Bucket: anchor.StorageDomain.LedgerBucket,
		KMSKeyID: anchor.StorageDomain.LedgerKMSKeyOCID, Prefix: anchor.StorageDomain.Prefix,
		HeadBucket: anchor.StorageDomain.HeadBucket, HeadKMSKeyID: anchor.StorageDomain.HeadKMSKeyOCID,
		Environment: anchor.Environment, ControllerSlots: controllerSlots, AnchorExpiresAt: fixture.anchor.ExpiresAt(),
		TrustRoots: fixture.authority.roots, Delegations: []trust.VerifiedDelegation{delegation},
		TrustPolicy: fixture.policy, VerificationNow: client.currentTime,
	}
	ledger, err := NewLedger(client, config)
	if err != nil {
		t.Fatalf("NewLedger(): %v", err)
	}
	profile := LaunchProfile{
		Slot: row.Slot, CompartmentOCID: row.CompartmentOCID, AvailabilityDomain: row.AvailabilityDomain,
		FaultDomain: row.FaultDomain, SubnetOCID: row.SubnetOCID,
		NetworkSecurityGroupOCIDs: slices.Clone(row.NetworkSecurityGroupOCIDs), Shape: row.Shape,
	}
	launchDigest, err := launchProfileDigest(profile)
	if err != nil {
		t.Fatal(err)
	}
	rowDigest, err := FounderPeerRowDigest(row)
	if err != nil {
		t.Fatal(err)
	}
	if planDigestPin == "" {
		planDigestPin = plan.Digest()
	}
	if rowDigestPin == "" {
		rowDigestPin = rowDigest
	}
	intent := Intent{
		SchemaVersion: 1, Mode: IntentModeManaged, DeploymentID: anchor.DeploymentID,
		Cell: string(anchor.Cell), Environment: anchor.Environment, Role: roleController, Slot: row.Slot,
		Attempt: 1, Generation: 1, ManifestDigest: row.ManifestSHA256,
		ReleaseReceiptDigest: digestBytes([]byte("release")), RegionIntentGeneration: anchor.InitialRegionIntentGeneration,
		ImageOCID: row.ImageOCID, RegionIntentDigest: anchor.InitialRegionIntentSHA256,
		LaunchRequestDigest: launchDigest, FounderPlanSHA256: planDigestPin, PeerRowDigest: rowDigestPin,
		CreateKey: "create-" + row.Slot, RetryToken: "retry-" + row.Slot, CreatedAt: fixture.now,
		OCIRegion: "sa-saopaulo-1", CompartmentOCID: row.CompartmentOCID,
		AvailabilityDomain: row.AvailabilityDomain, FaultDomain: row.FaultDomain, SubnetOCID: row.SubnetOCID,
		NetworkSecurityGroupIDs: slices.Clone(row.NetworkSecurityGroupOCIDs), Shape: row.Shape, Node: row.Slot,
	}
	scope := BootstrapScope{DeploymentID: anchor.DeploymentID, Cell: string(anchor.Cell), Slot: row.Slot}
	intentPayload, err := trust.EncodePayload(intent)
	if err != nil {
		t.Fatal(err)
	}
	intentEnvelope, err := trust.Sign(intentPayload, trust.Scope{
		Domain: domainBootstrapIntent, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
		Environment: anchor.Environment, Role: roleController, Slot: row.Slot,
	}, fixture.now, fixture.now.Add(23*time.Hour), fixture.authority.peerPrivate)
	if err != nil {
		t.Fatal(err)
	}
	intentWire, err := trust.EncodeEnvelope(intentEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	head := SlotHead{
		SchemaVersion: 1, DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: anchor.Environment,
		Role: roleController, Slot: row.Slot, Attempt: 1, Generation: 1, IntentDigest: digestBytes(intentWire),
	}
	headPayload, err := trust.EncodePayload(head)
	if err != nil {
		t.Fatal(err)
	}
	headEnvelope, err := trust.Sign(headPayload, trust.Scope{
		Domain: domainBootstrapHead, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
		Environment: anchor.Environment, Role: roleController, Slot: row.Slot,
	}, fixture.now, fixture.now.Add(23*time.Hour), fixture.authority.peerPrivate)
	if err != nil {
		t.Fatal(err)
	}
	headWire, err := trust.EncodeEnvelope(headEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := ledger.ReserveSlot(t.Context(), scope, intentWire, headWire); err != nil {
		t.Fatalf("ReserveSlot(): %v", err)
	}
	launch, err := ledger.ReadForLaunch(t.Context(), scope)
	if err != nil {
		t.Fatalf("ReadForLaunch(): %v", err)
	}
	return launch
}

func (verified VerifiedFounderPlan) AuthorizePeer(
	slot string,
	launch LaunchAuthorization,
	roots trust.Keyring,
	now time.Time,
	policy trust.Policy,
) (VerifiedFounderPeer, error) {
	if !verified.verified {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: verified founder plan is absent", ErrFounderPeerAuthorization)
	}
	current, err := VerifyFounderPlan(verified.wire, roots, verified.anchorWire, verified.manifestWires, now, policy)
	if err != nil {
		return VerifiedFounderPeer{}, err
	}
	return authorizeFounderPeer(current.snapshot(), slot, launch, now)
}

func authorizeFounderPeer(current founderPlanSnapshot, slot string, launch LaunchAuthorization, now time.Time) (VerifiedFounderPeer, error) {
	index := slices.IndexFunc(current.plan.Peers, func(row FounderPeerRow) bool { return row.Slot == slot })
	if index < 0 {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: slot %q is not a planned peer", ErrFounderPeerAuthorization, slot)
	}
	row := current.plan.Peers[index]
	rowDigest, err := FounderPeerRowDigest(row)
	if err != nil {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: hash peer row: %v", ErrFounderPeerAuthorization, err)
	}
	intent := launch.intent
	if intent.SchemaVersion != 1 {
		return VerifiedFounderPeer{}, ErrFounderPlanRequired
	}
	if !launch.ServerDate().IsZero() && now.Before(launch.ServerDate()) {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: founder-plan verification time predates the OCI launch read", ErrFounderPeerAuthorization)
	}
	if err := validateLaunchTokenBinding(launch, current, row, rowDigest); err != nil {
		return VerifiedFounderPeer{}, err
	}
	intentEnvelope, err := trust.DecodeEnvelope(launch.intentRecord.Bytes)
	if err != nil || !intentEnvelope.ExpiresAt.After(now) {
		return VerifiedFounderPeer{}, ErrFounderPlanExpired
	}
	retryDeadline := launch.intentRecord.LastModified.Add(maxRetryAge)
	if !now.Before(retryDeadline) {
		return VerifiedFounderPeer{}, ErrFounderPlanExpired
	}
	manifest := current.manifests[slot]
	deadline := earlierTime(current.plan.LaunchDeadline, current.expiresAt, current.anchorExpiresAt,
		manifest.ExpiresAt(), intentEnvelope.ExpiresAt, retryDeadline)
	if !now.Before(deadline) {
		return VerifiedFounderPeer{}, ErrFounderPlanExpired
	}
	return VerifiedFounderPeer{
		row: cloneFounderPeerRow(row), manifest: manifest, manifestWire: bytes.Clone(current.manifestWires[slot]), launch: launch,
		planDigest: current.digest, rowDigest: rowDigest, effectDeadline: deadline, verified: true,
	}, nil
}

func validateLaunchTokenBinding(launch LaunchAuthorization, plan founderPlanSnapshot, row FounderPeerRow, rowDigest string) error {
	intent := launch.intent
	intentEnvelope, intentEnvelopeErr := trust.DecodeEnvelope(launch.intentRecord.Bytes)
	headEnvelope, headEnvelopeErr := trust.DecodeEnvelope(launch.headRecord.Bytes)
	var recordIntent Intent
	var recordHead SlotHead
	if intentEnvelopeErr == nil {
		intentEnvelopeErr = decodeCanonicalPayload(intentEnvelope.Payload, &recordIntent)
	}
	if headEnvelopeErr == nil {
		headEnvelopeErr = decodeCanonicalPayload(headEnvelope.Payload, &recordHead)
	}
	intentScope := trust.Scope{
		Domain: domainBootstrapIntent, DeploymentID: intent.DeploymentID, Cell: intent.Cell,
		Environment: intent.Environment, Role: intent.Role, Slot: intent.Slot,
	}
	if launch.scope != (BootstrapScope{DeploymentID: plan.plan.DeploymentID, Cell: string(plan.plan.Cell), Slot: row.Slot}) ||
		intentEnvelopeErr != nil || headEnvelopeErr != nil || !sameIntent(recordIntent, intent) || !sameHead(recordHead, launch.head) ||
		launch.intentRecord.SHA256 == "" || digestBytes(launch.intentRecord.Bytes) != launch.intentRecord.SHA256 ||
		launch.headRecord.SHA256 == "" || digestBytes(launch.headRecord.Bytes) != launch.headRecord.SHA256 ||
		launch.head.SchemaVersion != 1 || launch.head.ResultDigest != "" || launch.head.IntentDigest != launch.intentRecord.SHA256 ||
		launch.head.Attempt != intent.Attempt || launch.head.Generation != intent.Generation ||
		intentScope != (trust.Scope{
			Domain: domainBootstrapIntent, DeploymentID: plan.plan.DeploymentID, Cell: string(plan.plan.Cell),
			Environment: plan.plan.Environment, Role: roleController, Slot: row.Slot,
		}) || headEnvelope.Scope != (trust.Scope{
		Domain: domainBootstrapHead, DeploymentID: plan.plan.DeploymentID, Cell: string(plan.plan.Cell),
		Environment: plan.plan.Environment, Role: roleController, Slot: row.Slot,
	}) || intent.SchemaVersion != 1 || intent.Mode != IntentModeManaged ||
		intent.FounderPlanSHA256 != plan.digest || intent.PeerRowDigest != rowDigest ||
		intent.ManifestDigest != row.ManifestSHA256 || intent.ImageOCID != row.ImageOCID ||
		!sameProfile(launchProfileForIntent(intent), LaunchProfile{
			Slot: row.Slot, CompartmentOCID: row.CompartmentOCID, AvailabilityDomain: row.AvailabilityDomain,
			FaultDomain: row.FaultDomain, SubnetOCID: row.SubnetOCID,
			NetworkSecurityGroupOCIDs: row.NetworkSecurityGroupOCIDs, Shape: row.Shape,
		}) || !createTokenPattern.MatchString(intent.CreateKey) || !createTokenPattern.MatchString(intent.RetryToken) {
		return fmt.Errorf("%w: ReadForLaunch token does not pin this exact founder plan row", ErrFounderPeerAuthorization)
	}
	if err := CheckRetryWindow(launch.intentRecord); err != nil {
		return fmt.Errorf("%w: original intent retry window is not current: %v", ErrFounderPlanExpired, err)
	}
	return nil
}

// IsVerified reports whether this value came from VerifiedFounderPlan.AuthorizePeer.
func (verified VerifiedFounderPeer) IsVerified() bool { return verified.verified }

// EffectDeadline is the earliest signed-plan, anchor, or manifest deadline.
// Launchable recovery phases also include the original intent and OCI retry
// deadlines; observation and already-written-result recovery do not renew or
// depend on that retry window.
func (verified VerifiedFounderPeer) EffectDeadline() time.Time { return verified.effectDeadline }

// StartupAuthority returns the actual root or source-derived startup seal.
func (verified VerifiedFounderPeer) StartupAuthority() StartupAuthority {
	if !verified.verified {
		return nil
	}
	return verified.manifest
}

// Manifest returns the render-only manifest from the verified startup proof.
func (verified VerifiedFounderPeer) Manifest() Manifest {
	if !verified.verified {
		return Manifest{}
	}
	return verified.manifest.Manifest()
}

// LaunchRequest returns a defensive request while the captured signed
// intervals and original OCI retry deadline remain current. It does not refresh
// authority or ledger state; callers must freshly read the selected authority
// snapshot and ledger immediately before every effect and retry.
func (verified VerifiedFounderPeer) LaunchRequest(now time.Time) (FounderPeerLaunchRequest, error) {
	if !verified.verified || !validFounderNow(now) {
		return FounderPeerLaunchRequest{}, ErrFounderPeerAuthorization
	}
	if verified.recovery != nil {
		authorizationTime := verified.recovery.AuthorizationTime()
		if authorizationTime.IsZero() {
			return FounderPeerLaunchRequest{}, ErrFounderPeerAuthorization
		}
		if now.Before(authorizationTime) {
			now = authorizationTime
		}
	}
	if !verified.launch.intentRecord.ServerDate.IsZero() && now.Before(verified.launch.intentRecord.ServerDate) {
		return FounderPeerLaunchRequest{}, fmt.Errorf("%w: request time predates the OCI launch read", ErrFounderPeerAuthorization)
	}
	if verified.recovery != nil && now.Before(verified.recovery.serverDate.Add(time.Second)) {
		return FounderPeerLaunchRequest{}, fmt.Errorf("%w: request time predates the final OCI recovery read", ErrFounderPeerAuthorization)
	}
	if !now.Before(verified.effectDeadline) {
		return FounderPeerLaunchRequest{}, ErrFounderPlanExpired
	}
	if verified.recovery != nil && verified.recovery.phase != ManagedPeerRecoveryClean &&
		verified.recovery.phase != ManagedPeerRecoveryManifestOnly {
		return FounderPeerLaunchRequest{}, fmt.Errorf("%w: recovery phase %q does not authorize an OCI launch", ErrFounderPeerAuthorization, verified.recovery.phase)
	}
	return verified.launchRequest(), nil
}

func (verified VerifiedFounderPeer) launchRequest() FounderPeerLaunchRequest {
	intent := verified.launch.intent
	return FounderPeerLaunchRequest{
		StartupAuthority: verified.manifest,
		DeploymentID:     intent.DeploymentID, Cell: oci.Region(intent.Cell), Environment: intent.Environment,
		Slot: intent.Slot, Node: intent.Node, Attempt: intent.Attempt, Generation: intent.Generation,
		IntentSHA256: verified.launch.intentRecord.SHA256, FounderPlanSHA256: verified.planDigest,
		PeerRowSHA256: verified.rowDigest, ManifestSHA256: verified.row.ManifestSHA256,
		ManifestWire: bytes.Clone(verified.manifestWire),
		CreateKey:    intent.CreateKey, RetryToken: intent.RetryToken, HeadETag: verified.launch.headRecord.ETag,
		Row: cloneFounderPeerRow(verified.row),
	}
}

func NewLedger(client ObjectStorageClient, config LedgerConfig) (*Ledger, error) {
	return newLedger(client, config, false)
}

// NewHistoricalLedger constructs an evidence-only reader for the current
// five-domain ledger grant. Its write paths remain
// disabled even if the caller later invokes a mutation method.
func NewHistoricalLedger(client ObjectStorageClient, config LedgerConfig) (*Ledger, error) {
	return newLedger(client, config, true)
}

func newLedger(client ObjectStorageClient, config LedgerConfig, historical bool) (*Ledger, error) {
	if client == nil || validateLedgerAnchor(config) != nil || !ledgerIDPattern.MatchString(config.Namespace) ||
		!ledgerNamePattern.MatchString(config.Bucket) || !strings.HasPrefix(config.KMSKeyID, "ocid1.key.") ||
		len(config.KMSKeyID) > 255 || strings.ContainsAny(config.KMSKeyID, " \t\r\n") || !validLedgerPrefix(config.Prefix) ||
		!ledgerNamePattern.MatchString(config.HeadBucket) || config.HeadBucket == config.Bucket ||
		!strings.HasPrefix(config.HeadKMSKeyID, "ocid1.key.") || len(config.HeadKMSKeyID) > 255 ||
		strings.ContainsAny(config.HeadKMSKeyID, " \t\r\n") ||
		!ledgerIDPattern.MatchString(config.Environment) || config.TrustPolicy.MaxLifetime <= 0 || config.TrustPolicy.ClockSkew < 0 ||
		len(config.ControllerSlots) == 0 || len(config.ControllerSlots) > 64 || hasDuplicate(config.ControllerSlots) ||
		len(config.TrustRoots) == 0 && len(config.Delegations) == 0 || validateLedgerDelegations(config) != nil {
		return nil, errors.New("bootstrap ledger requires separate immutable and coordination buckets, KMS keys, environment, trust policy, and a valid Object Storage client")
	}
	for _, slot := range config.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) {
			return nil, errors.New("bootstrap ledger requires a canonical anchor-pinned controller slot set")
		}
	}
	roots := make(trust.Keyring, len(config.TrustRoots))
	for keyID, key := range config.TrustRoots {
		roots[keyID] = bytes.Clone(key)
	}
	config.TrustRoots = roots
	config.Delegations = slices.Clone(config.Delegations)
	if config.DerivedStartup != nil {
		config.DerivedStartup = new(*config.DerivedStartup)
	}
	config.ControllerSlots = slices.Clone(config.ControllerSlots)
	if config.VerificationNow == nil {
		config.VerificationNow = time.Now
	}
	return &Ledger{client: client, config: config, maxRecord: maxLedgerRecordBytes, readOnly: historical}, nil
}

func validateLedgerDelegations(config LedgerConfig) error {
	if config.DerivedStartup != nil {
		authority := *config.DerivedStartup
		manifest := authority.Manifest()
		if authority.verifyStartupAuthority() != nil || manifest.DeploymentID != config.DeploymentID || manifest.Environment != config.Environment || manifest.ClusterID != config.ClusterID || manifest.Cell != config.Cell || manifest.StorageDomain != config.storageDomain() || !slices.Equal(manifest.ControllerSlots, config.ControllerSlots) || manifest.IntentGeneration != config.InitialRegionIntentGeneration || manifest.IntentSHA256 != config.InitialRegionIntentSHA256 {
			return ErrRecordAuthorization
		}
		if authority.template.startupIdentity().InitialSourceRegistration != nil {
			if len(config.Delegations) != 0 {
				return ErrRecordAuthorization
			}
			return nil
		}
	}
	if len(config.Delegations) != 1 {
		return errors.New("bootstrap ledger requires exactly one anchor-verified ledger delegation")
	}
	wantDomains := BootstrapLedgerCapabilityDomains()
	capabilities := config.Delegations[0].Capabilities()
	if len(capabilities) != len(wantDomains) {
		return fmt.Errorf("bootstrap ledger delegation must contain exactly %d record grants", len(wantDomains))
	}
	seen := make(map[string]struct{}, len(capabilities))
	for _, capability := range capabilities {
		if !slices.Contains(wantDomains, capability.Domain) || capability.DeploymentID != config.DeploymentID ||
			capability.Cell != string(config.Cell) || capability.Environment != config.Environment || capability.Role != roleController ||
			!sameStrings(capability.Slots, config.ControllerSlots) || !slices.Equal(capability.Actions, []string{"sign"}) {
			return errors.New("bootstrap ledger delegation does not match the exact anchored scope and slots")
		}
		if _, exists := seen[capability.Domain]; exists {
			return errors.New("bootstrap ledger delegation duplicates a signing domain")
		}
		seen[capability.Domain] = struct{}{}
	}
	return nil
}

func validateLedgerAnchor(config LedgerConfig) error {
	if !entityid.Valid(config.DeploymentID) || !entityid.Valid(config.ClusterID) ||
		config.InitialRegionIntentGeneration == 0 || !validDigest(config.InitialRegionIntentSHA256) {
		return errors.New("bootstrap ledger requires trusted deployment, cluster, and initial region-intent identity")
	}
	if _, err := config.Cell.OCIRegion(); err != nil {
		return fmt.Errorf("bootstrap ledger requires a supported trusted cell: %w", err)
	}
	return nil
}

// CheckRetryWindow compares OCI's current server clock to the original
// object's Last-Modified time. Missing or inconsistent clock metadata fails
// closed; callers must hold once the 23-hour OCI create-token window expires.
func CheckRetryWindow(record StoredRecord) error {
	if record.LastModified.IsZero() || record.ServerDate.IsZero() || record.ServerDate.Before(record.LastModified) {
		return ErrInvalidRetryClock
	}
	if record.ServerDate.Sub(record.LastModified) >= maxRetryAge {
		return ErrRetryWindowExpired
	}
	return nil
}

func (ledger *Ledger) createOrReadNamed(ctx context.Context, scope BootstrapScope, attempt uint64,
	kind ledgerRecordKind, objectName string, body []byte,
) (StoredRecord, error) {
	if err := validateLedgerScope(scope); err != nil {
		return StoredRecord{}, err
	}
	if attempt == 0 || objectName == "" || len(body) == 0 || len(body) > ledger.maxRecord {
		return StoredRecord{}, errors.New("bootstrap ledger record is empty or exceeds its size bound")
	}
	sourceDigest := sha256.Sum256(body)
	ifNoneMatch := "*"
	digestHeader := base64.StdEncoding.EncodeToString(sourceDigest[:])
	length := int64(len(body))
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return StoredRecord{}, err
	}
	envelope, err := trust.DecodeEnvelope(body)
	if err != nil {
		return StoredRecord{}, fmt.Errorf("%w: decode bootstrap record envelope before write: %v", ErrInvalidRecord, err)
	}
	request := objectstorage.PutObjectRequest{
		NamespaceName:        new(ledger.config.Namespace),
		BucketName:           new(ledger.config.Bucket),
		ObjectName:           new(objectName),
		PutObjectBody:        io.NopCloser(bytes.NewReader(body)),
		ContentLength:        &length,
		ContentType:          new("application/json"),
		IfNoneMatch:          &ifNoneMatch,
		OpcSseKmsKeyId:       new(ledger.config.KMSKeyID),
		OpcChecksumAlgorithm: objectstorage.PutObjectOpcChecksumAlgorithmSha256,
		OpcContentSha256:     &digestHeader,
	}
	response, putErr, putAttempted := ledger.putObjectAfterTimestampBoundary(ctx, request, envelope)
	if putErr != nil && (!putAttempted || !shouldReadAfterPutError(putErr)) {
		return StoredRecord{}, fmt.Errorf("create immutable bootstrap %s: %w", kind, putErr)
	}
	stored, readErr := ledger.readObject(ctx, ledger.config.Bucket, objectName)
	if readErr != nil {
		if putErr != nil && errors.Is(readErr, ErrRecordMissing) {
			return StoredRecord{}, fmt.Errorf("%w: create immutable bootstrap %s: %v; exact-key read: %w", ErrOutcomeUnknown, kind, putErr, readErr)
		}
		if putErr == nil {
			return StoredRecord{}, fmt.Errorf("%w: acknowledged bootstrap %s is unavailable on exact-key read: %w", ErrOutcomeUnknown, kind, readErr)
		}
		return StoredRecord{}, fmt.Errorf("%w: create immutable bootstrap %s: %v; exact-key read: %w", ErrOutcomeUnknown, kind, putErr, readErr)
	}
	if !bytes.Equal(stored.Bytes, body) {
		return StoredRecord{}, ErrImmutableConflict
	}
	if putErr == nil && response.ETag != nil && *response.ETag != "" && stored.ETag != *response.ETag {
		return StoredRecord{}, fmt.Errorf("%w: acknowledged ETag differs from exact-key read", ErrImmutableConflict)
	}
	stored.Created = putErr == nil
	return stored, nil
}

func (ledger *Ledger) putObjectAfterTimestampBoundary(
	ctx context.Context,
	request objectstorage.PutObjectRequest,
	envelope trust.Envelope,
) (objectstorage.PutObjectResponse, error, bool) {
	if err := waitForLedgerRecordStorageBoundary(ctx, envelope, ledger.now); err != nil {
		return objectstorage.PutObjectResponse{}, err, false
	}
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return objectstorage.PutObjectResponse{}, err, false
	}
	if err := ctx.Err(); err != nil {
		return objectstorage.PutObjectResponse{}, err, false
	}
	if err := validateLedgerRecordStorageBucket(envelope, ledger.now()); err != nil {
		return objectstorage.PutObjectResponse{}, err, false
	}
	response, err := ledger.client.PutObject(ociclient.RequestContext(ctx), request)
	return response, err, true
}

func waitForLedgerRecordStorageBoundary(ctx context.Context, envelope trust.Envelope, now func() time.Time) error {
	storageAt, err := firstLedgerRecordStorageBucket(envelope)
	if err != nil {
		return err
	}
	if !storedBeforeExpiry(storageAt, envelope.ExpiresAt) {
		return fmt.Errorf("%w: no whole-second Object Storage timestamp fits before signature expiry", ErrRecordAuthorization)
	}
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		current := now().UTC()
		if !current.Truncate(time.Second).Before(storageAt) {
			return nil
		}
		wait := storageAt.Sub(current)
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			if !timer.Stop() {
				select {
				case <-timer.C:
				default:
				}
			}
			return ctx.Err()
		case <-timer.C:
			if err := ctx.Err(); err != nil {
				return err
			}
			if !now().After(current) {
				return fmt.Errorf("%w: storage boundary clock did not advance", ErrRecordAuthorization)
			}
		}
	}
}

func firstLedgerRecordStorageBucket(envelope trust.Envelope) (time.Time, error) {
	if envelope.IssuedAt.IsZero() || envelope.ExpiresAt.IsZero() || !envelope.ExpiresAt.After(envelope.IssuedAt) {
		return time.Time{}, fmt.Errorf("%w: bootstrap record has no valid signed storage interval", ErrInvalidRecord)
	}
	storageAt := envelope.IssuedAt.UTC().Truncate(time.Second)
	if storageAt.Before(envelope.IssuedAt) {
		storageAt = storageAt.Add(time.Second)
	}
	return storageAt, nil
}

func validateLedgerRecordStorageBucket(envelope trust.Envelope, now time.Time) error {
	firstStorageAt, err := firstLedgerRecordStorageBucket(envelope)
	if err != nil {
		return err
	}
	storageAt := now.UTC().Truncate(time.Second)
	if storageAt.Before(firstStorageAt) {
		return fmt.Errorf("%w: current Object Storage timestamp precedes the signed issue boundary", ErrRecordAuthorization)
	}
	if !storedBeforeExpiry(storageAt, envelope.ExpiresAt) {
		return fmt.Errorf("%w: current Object Storage timestamp does not fit before signature expiry", ErrRecordAuthorization)
	}
	return nil

func (ledger *Ledger) readObject(ctx context.Context, bucket, objectName string) (StoredRecord, error) {
	return ledger.readObjectLimit(ctx, bucket, objectName, ledger.maxRecord)
}

func (ledger *Ledger) readObjectLimit(ctx context.Context, bucket, objectName string, maximum int) (StoredRecord, error) {
	if ledger.config.DerivedStartup != nil {
		authority := *ledger.config.DerivedStartup
		if ledger.now().Before(authority.ExpiresAt()) {
			if err := authority.VerifyCurrent(ctx, ledger.now()); err != nil {
				return StoredRecord{}, err
			}
		} else if _, err := authority.historical(ctx, authority.Wire()); err != nil {
			return StoredRecord{}, err
		}
	}
	response, err := ledger.client.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{
		NamespaceName: new(ledger.config.Namespace),
		BucketName:    new(bucket),
		ObjectName:    new(objectName),
	})
	if err != nil {
		if serviceErr, ok := errors.AsType[objectStorageServiceError](err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return StoredRecord{}, ErrRecordMissing
		}
		return StoredRecord{}, fmt.Errorf("read exact bootstrap object: %w", err)
	}
	if response.Content == nil {
		return StoredRecord{}, errors.New("bootstrap object response has no body")
	}
	if response.ContentLength == nil || *response.ContentLength < 1 || *response.ContentLength > int64(maximum) {
		response.Content.Close()
		return StoredRecord{}, errors.New("bootstrap object has missing or invalid content length")
	}
	body, err := io.ReadAll(io.LimitReader(response.Content, int64(maximum)+1))
	closeErr := response.Content.Close()
	if err := errors.Join(err, closeErr); err != nil {
		return StoredRecord{}, fmt.Errorf("read bootstrap object body: %w", err)
	}
	if len(body) != int(*response.ContentLength) || len(body) > maximum {
		return StoredRecord{}, errors.New("bootstrap object body length does not match its metadata")
	}
	if response.ETag == nil || strings.TrimSpace(*response.ETag) == "" || response.LastModified == nil {
		return StoredRecord{}, errors.New("bootstrap object is missing ETag or Last-Modified metadata")
	}
	if response.RawResponse == nil {
		return StoredRecord{}, errors.New("bootstrap object response is missing server headers")
	}
	serverDate, err := http.ParseTime(response.RawResponse.Header.Get("Date"))
	if err != nil {
		return StoredRecord{}, errors.New("bootstrap object response has a missing or invalid server Date")
	}
	lastModified := response.LastModified.Time.UTC()
	serverDate = serverDate.UTC()
	if lastModified.IsZero() || serverDate.Before(lastModified) {
		return StoredRecord{}, errors.New("bootstrap object server timestamps are inconsistent")
	}
	digest := sha256.Sum256(body)
	return StoredRecord{
		Bytes: body, SHA256: hex.EncodeToString(digest[:]), ETag: *response.ETag,
		LastModified: lastModified, ServerDate: serverDate,
	}, nil
}

func (ledger *Ledger) ReserveSlot(ctx context.Context, scope BootstrapScope, intentBytes, initialHeadBytes []byte) (SlotState, error) {
	if err := validateLedgerScope(scope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateAnchorScope(scope); err != nil {
		return SlotState{}, err
	}
	intent, intentEnvelope, intentErr := ledger.decodeIntent(scope, intentBytes, true)
	if intentErr != nil {
		return SlotState{}, intentErr
	}
	if intent.Attempt != 1 || intent.Generation != 1 {
		return SlotState{}, fmt.Errorf("%w: an initial reservation must begin at attempt and generation one", ErrInvalidRecord)
	}
	head, headErr := ledger.decodeHead(scope, initialHeadBytes, true)
	headAuthorizedNow := headErr == nil
	if headErr != nil {
		return SlotState{}, headErr
	}
	if head.Attempt != intent.Attempt || head.Generation != intent.Generation || head.IntentDigest != objectDigest(intentBytes) ||
		head.ResultDigest != "" || head.CandidateDigest != "" || head.PreviousAttempt != 0 || head.RetirementDigest != "" {
		return SlotState{}, ErrSlotNotReserved
	}
	intentRecord, err := ledger.createOrRead(ctx, scope, intent.Attempt, ledgerIntent, intentBytes)
	if err != nil {
		return SlotState{}, err
	}
	clockErr := validIntentClock(intent, intentRecord, ledger.config.TrustPolicy.ClockSkew)
	if clockErr != nil {
		return SlotState{}, clockErr
	}
	if err := validateStoredInterval(intentRecord, intentEnvelope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(intentRecord); err != nil {
		return SlotState{}, err
	}
	// Intent creation and HEAD admission are separate Object Storage calls. The
	// intent may expire while the HEAD write is in flight, so verify current
	// authority again immediately before admitting the initial HEAD.
	currentIntent, currentIntentRecord, err := ledger.refreshCurrentIntent(ctx, scope, intent, intentBytes)
	if err != nil {
		return SlotState{}, err
	}
	if !sameIntent(currentIntent, intent) || currentIntentRecord.SHA256 != intentRecord.SHA256 {
		return SlotState{}, ErrRecordAuthorization
	}
	intentRecord = currentIntentRecord
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return SlotState{}, err
	}
	_, headRecord, err := ledger.writeInitialHead(ctx, scope, head, initialHeadBytes, headAuthorizedNow)
	if err != nil {
		return SlotState{}, err
	}
	if err := validateStoredBeforeExpiry(headRecord, intentEnvelope.ExpiresAt); err != nil {
		return SlotState{}, err
	}
	if err := validateHeadWithinRetryWindow(headRecord, intentRecord); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(headRecord); err != nil {
		return SlotState{}, err
	}
	return ledger.ReadSlot(ctx, scope)
}

// ReadSlot returns a historically verified record view. It does not authorize
// a cloud mutation; use ReadForLaunch for a current signed, unexpired intent.
func (ledger *Ledger) ReadSlot(ctx context.Context, scope BootstrapScope) (SlotState, error) {
	state, err := ledger.readSlot(ctx, scope, false)
	if err == nil {
		return state, nil
	}
	// Managed peer records can be valid historical evidence whose
	// signed interval or exact proof timing is no longer current. Preserve that
	// distinction for read-only callers while keeping malformed or mismatched
	// records as hard errors.
	quarantined, recoveryErr := ledger.readSlotWithRecovery(ctx, scope, false, true)
	if recoveryErr == nil && quarantined.Intent.Mode == IntentModeManaged &&
		quarantined.quarantined {
		return SlotState{}, fmt.Errorf("%w: slot %q", ErrManagedPeerProofQuarantined, scope.Slot)
	}
	return SlotState{}, err
}

// ReadForLaunch returns a launch token only when the current signed intent is
// the exact attempt referenced by HEAD, has no committed positive result, and
// remains inside the original OCI retry window.
func (ledger *Ledger) ReadForLaunch(ctx context.Context, scope BootstrapScope) (LaunchAuthorization, error) {
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return LaunchAuthorization{}, err
	}
	state, err := ledger.readSlot(ctx, scope, true)
	if err != nil {
		return LaunchAuthorization{}, err
	}
	if state.Head.ResultDigest != "" {
		return LaunchAuthorization{}, ErrSlotAlreadyComplete
	}
	if state.Intent.Mode == IntentModeExternalSeed {
		return LaunchAuthorization{}, ErrExternalSeedMode
	}
	if state.Head.Attempt == ^uint64(0) {
		return LaunchAuthorization{}, fmt.Errorf("%w: slot attempt sequence is exhausted", ErrInvalidRecord)
	}
	if _, err := ledger.read(ctx, scope, state.Head.Attempt+1, ledgerIntent); err == nil {
		return LaunchAuthorization{}, ErrSlotAdvancePendingHead
	} else if !errors.Is(err, ErrRecordMissing) {
		return LaunchAuthorization{}, err
	}
	if state.CandidateRecord != nil {
		return LaunchAuthorization{}, ErrManagedPeerCandidatePinned
	}
	if _, err := ledger.read(ctx, scope, state.Head.Attempt, ledgerResult); err == nil {
		return LaunchAuthorization{}, ErrSlotResultPendingHead
	} else if !errors.Is(err, ErrRecordMissing) {
		return LaunchAuthorization{}, err
	}
	if err := CheckRetryWindow(state.IntentRecord); err != nil {
		return LaunchAuthorization{}, err
	}
	if state.ManifestRecord != nil || state.PeerReceiptRecord != nil {
		return LaunchAuthorization{}, ErrSlotResultPendingHead
	}
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return LaunchAuthorization{}, err
	}
	currentIntent, currentIntentRecord, err := ledger.refreshCurrentIntent(ctx, scope, state.Intent, state.IntentRecord.Bytes)
	if err != nil {
		return LaunchAuthorization{}, err
	}
	if !sameIntent(currentIntent, state.Intent) || currentIntentRecord.SHA256 != state.IntentRecord.SHA256 {
		return LaunchAuthorization{}, ErrRecordAuthorization
	}
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return LaunchAuthorization{}, err
	}
	return LaunchAuthorization{
		scope: scope, intent: currentIntent, intentRecord: currentIntentRecord,
		head: state.Head, headRecord: state.HeadRecord,
	}, nil
}

func (ledger *Ledger) readSlot(ctx context.Context, scope BootstrapScope, requireCurrentIntent bool) (SlotState, error) {
	return ledger.readSlotWithRecovery(ctx, scope, requireCurrentIntent, false)
}

func (ledger *Ledger) readSlotForManagedPeerRecovery(ctx context.Context, scope BootstrapScope) (SlotState, error) {
	return ledger.readSlotWithRecovery(ctx, scope, false, true)
}

func (ledger *Ledger) readSlotWithRecovery(
	ctx context.Context,
	scope BootstrapScope,
	requireCurrentIntent bool,
	allowExpiredUnfinishedRecovery bool,
) (SlotState, error) {
	if err := validateLedgerScope(scope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateAnchorScope(scope); err != nil {
		return SlotState{}, err
	}
	headRecord, err := ledger.readObject(ctx, ledger.config.HeadBucket, ledger.headObjectName(scope))
	if err != nil {
		return SlotState{}, err
	}
	headEnvelope, err := trust.DecodeEnvelope(headRecord.Bytes)
	if err != nil {
		return SlotState{}, fmt.Errorf("%w: decode persisted HEAD envelope: %v", ErrInvalidRecord, err)
	}
	quarantined := false
	if err := validateStoredInterval(headRecord, headEnvelope); err != nil {
		if !allowExpiredUnfinishedRecovery {
			return SlotState{}, err
		}
		quarantined = true
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(headRecord); err != nil {
		if !allowExpiredUnfinishedRecovery {
			return SlotState{}, err
		}
		quarantined = true
	}
	head, err := ledger.decodeHead(scope, headRecord.Bytes, false)
	if err != nil {
		return SlotState{}, err
	}
	intentRecord, err := ledger.read(ctx, scope, head.Attempt, ledgerIntent)
	if err != nil {
		return SlotState{}, fmt.Errorf("read HEAD-referenced intent: %w", err)
	}
	intent, intentEnvelope, err := ledger.decodeIntent(scope, intentRecord.Bytes, requireCurrentIntent)
	if err != nil {
		return SlotState{}, err
	}
	if err := validateStoredInterval(intentRecord, intentEnvelope); err != nil {
		if !allowExpiredUnfinishedRecovery {
			return SlotState{}, err
		}
		quarantined = true
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(intentRecord); err != nil {
		if !allowExpiredUnfinishedRecovery {
			return SlotState{}, err
		}
		quarantined = true
	}
	if err := validateStoredBeforeExpiry(headRecord, intentEnvelope.ExpiresAt); err != nil {
		if !allowExpiredUnfinishedRecovery {
			return SlotState{}, err
		}
		quarantined = true
	}
	if head.ResultDigest == "" && !allowExpiredUnfinishedRecovery {
		if err := validateHeadWithinRetryWindow(headRecord, intentRecord); err != nil {
			return SlotState{}, err
		}
	}
	if intent.Attempt != head.Attempt || intent.Generation != head.Generation || intentRecord.SHA256 != head.IntentDigest {
		return SlotState{}, ErrSlotNotReserved
	}

state := SlotState{Head: head, HeadRecord: headRecord, Intent: intent, IntentRecord: intentRecord,
	quarantined: quarantined}
if intent.Mode == IntentModeManaged {
	if _, err := ledger.read(ctx, scope, head.Attempt, ledgerSeedReceipt); err == nil {
		return SlotState{}, ErrSlotNotReserved
	} else if !errors.Is(err, ErrRecordMissing) {
		return SlotState{}, err
	}
	return ledger.readManagedPeerState(ctx, scope, state, allowExpiredUnfinishedRecovery)
}

type fakeObjectStorageClient struct {
	mu               sync.Mutex
	objects          map[string]fakeStoredObject
	clockAtCommit    map[string]time.Time
	clockAtGet       map[string]fakeClockAdvance
	getsByObject     map[string]int
	now              time.Time
	loseAckBucket    string
	putCalls         atomic.Int32
	getCalls         atomic.Int32
	invalidCondition atomic.Bool
	invalidKMSKey    atomic.Bool
	omitServerDate   atomic.Bool
	failBeforeCommit atomic.Bool
	rejectPut        error
	rejectPutBucket  string
}

type fakeClockAdvance struct {
	getNumber int
	now       time.Time
}

type fakeStoredObject struct {
	body         []byte
	etag         string
	lastModified time.Time
}

func newFakeObjectStorageClient() *fakeObjectStorageClient {
	return &fakeObjectStorageClient{
		objects: make(map[string]fakeStoredObject), clockAtCommit: make(map[string]time.Time),
		clockAtGet: make(map[string]fakeClockAdvance), getsByObject: make(map[string]int),
		now: time.Now().UTC().Truncate(time.Second),
	}
}

func (client *fakeObjectStorageClient) currentTime() time.Time {
	client.mu.Lock()
	defer client.mu.Unlock()
	return client.now
}

func (client *fakeObjectStorageClient) setNow(now time.Time) {
	client.mu.Lock()
	client.now = now.UTC()
	client.mu.Unlock()
}

func (client *fakeObjectStorageClient) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	client.putCalls.Add(1)
	if request.IfNoneMatch == nil && request.IfMatch == nil || request.IfNoneMatch != nil && request.IfMatch != nil ||
		request.IfNoneMatch != nil && *request.IfNoneMatch != "*" {
		client.invalidCondition.Store(true)
	}
	expectedKey := "ocid1.key.oc1.sa-saopaulo-1.ledger"
	if request.BucketName != nil && *request.BucketName == "bootstrap-head" {
		expectedKey = "ocid1.key.oc1.sa-saopaulo-1.head"
	}
	if request.OpcSseKmsKeyId == nil || *request.OpcSseKmsKeyId != expectedKey {
		client.invalidKMSKey.Store(true)
	}
	body, err := io.ReadAll(request.PutObjectBody)
	if closeErr := request.PutObjectBody.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return objectstorage.PutObjectResponse{}, err
	}
	if request.ContentLength == nil || int64(len(body)) != *request.ContentLength {
		return objectstorage.PutObjectResponse{}, errors.New("incorrect content length")
	}
	digest := sha256.Sum256(body)
	digestHeader := base64.StdEncoding.EncodeToString(digest[:])
	if request.OpcContentSha256 == nil || *request.OpcContentSha256 != digestHeader ||
		request.OpcChecksumAlgorithm != objectstorage.PutObjectOpcChecksumAlgorithmSha256 {
		return objectstorage.PutObjectResponse{}, errors.New("incorrect SHA-256 checksum")
	}
	if client.failBeforeCommit.Swap(false) {
		return objectstorage.PutObjectResponse{}, errors.New("connection reset before object commit")
	}
	if client.rejectPut != nil && (client.rejectPutBucket == "" || request.BucketName != nil && *request.BucketName == client.rejectPutBucket) {
		return objectstorage.PutObjectResponse{}, client.rejectPut
	}
	key := requestKey(request.NamespaceName, request.BucketName, request.ObjectName)
	client.mu.Lock()
	if advanceTo, ok := client.clockAtCommit[key]; ok {
		client.now = advanceTo
		delete(client.clockAtCommit, key)
	}
	previous, exists := client.objects[key]
	if request.IfNoneMatch != nil && exists || request.IfMatch != nil && (!exists || *request.IfMatch != previous.etag) {
		client.mu.Unlock()
		return objectstorage.PutObjectResponse{}, fakeObjectStorageError{status: http.StatusPreconditionFailed}
	}
	etag := `"` + hex.EncodeToString(digest[:8]) + `"`
	client.objects[key] = fakeStoredObject{
		body: bytes.Clone(body), etag: etag, lastModified: client.now.UTC().Truncate(time.Second),
	}
	loseAck := client.loseAckBucket != "" && request.BucketName != nil && *request.BucketName == client.loseAckBucket
	if loseAck {
		client.loseAckBucket = ""
	}
	client.mu.Unlock()
	if loseAck {
		return objectstorage.PutObjectResponse{}, errors.New("connection reset after object commit")
	}
	return objectstorage.PutObjectResponse{ETag: &etag, OpcRequestId: new("fake-put-request")}, nil
}

func (client *fakeObjectStorageClient) GetObject(_ context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	client.getCalls.Add(1)
	key := requestKey(request.NamespaceName, request.BucketName, request.ObjectName)
	client.mu.Lock()
	client.getsByObject[key]++
	if advance, ok := client.clockAtGet[key]; ok && client.getsByObject[key] == advance.getNumber {
		client.now = advance.now
		delete(client.clockAtGet, key)
	}
	object, ok := client.objects[key]
	now := client.now
	client.mu.Unlock()
	if !ok {
		return objectstorage.GetObjectResponse{}, fakeObjectStorageError{status: http.StatusNotFound}
	}
	date := now.Format(http.TimeFormat)
	if client.omitServerDate.Load() {
		date = ""
	}
	headers := make(http.Header)
	if date != "" {
		headers.Set("Date", date)
	}
	length := int64(len(object.body))
	etag := object.etag
	lastModified := common.SDKTime{Time: object.lastModified}
	return objectstorage.GetObjectResponse{
		RawResponse: &http.Response{Header: headers}, Content: io.NopCloser(bytes.NewReader(object.body)),
		ContentLength: &length, ETag: &etag, LastModified: &lastModified, OpcRequestId: new("fake-get-request"),
	}, nil
}

